class Inventory {
  constructor() {
    this.items = {};
  }

  add(name, qty) {
    if (this.items[name]) {
      this.items[name] += qty;
    } else {
      this.items[name] = qty;
    }
  }

  count(name) {
    return this.items[name] || 0;
  }

  remove(name, qty) {
    if (this.items[name] && this.items[name] >= qty) {
      this.items[name] -= qty;
      if (this.items[name] === 0) {
        delete this.items[name];
      }
    } else {
      throw new Error(`Not enough ${name} to remove.`);
    }
  }
}

module.exports = Inventory;

